async function cut(p){guard();const b=bot.blockAt(p);if(b?.boundingBox==='empty')return;if(!materials.includes(b?.name))throw Error('CUT_PRE '+p+' '+b?.name);if(Object.values(bot.entities).some(e=>e.type==='player'&&e.id!==bot.entity.id&&e.position.distanceTo(p.offset(.5,.5,.5))<1.25))throw Error('PEER_CUT '+p);for(const d of [...dirs,new Vec3(0,1,0),new Vec3(0,-1,0)])if(['lava','water','fire','soul_fire','sand','gravel'].includes(bot.blockAt(p.plus(d))?.name))throw Error('CUT_HAZARD');const pick=bot.inventory.items().filter(i=>['iron_pickaxe','stone_pickaxe'].includes(i.name)&&i.durabilityUsed<({iron_pickaxe:249,stone_pickaxe:130}[i.name])).sort((a,b)=>(a.name==='iron_pickaxe')-(b.name==='iron_pickaxe')||a.durabilityUsed-b.durabilityUsed)[0];if(!pick)throw Error('NO_PICK');bot.deactivateItem();await bot.equip(pick,'hand');await ticks(3);const ms=bot.digTime(b)+2000;if(ms>10000)throw Error('DIG_COST');let t;try{await Promise.race([bot.dig(b,true,'raycast'),new Promise((_,r)=>t=setTimeout(()=>{bot.stopDigging();r(Error('DIG_BOUND'))},ms))]);}finally{clearTimeout(t)}await ticks(5);if(bot.blockAt(p)?.boundingBox!=='empty')throw Error('CUT_POST');}
async function pathGo(p,recovery=false){life();if(!cold(p))throw Error('COLD_PRE '+p);if(!recovery)guard();const m=new Movements(bot);m.canDig=false;m.allowSprinting=false;m.allowParkour=false;m.allow1by1towers=false;m.scafoldingBlocks=[];m.maxDropDown=2;m.getMoveDiagonal=()=>{};const old=m.getNeighbors.bind(m);m.getNeighbors=n=>old(n).filter(k=>cold(new Vec3(k.x,k.y,k.z)));bot.pathfinder.setMovements(m);bot.pathfinder.thinkTimeout=500;const goal=new goals.GoalBlock(p.x,p.y,p.z);bot.activateItem(true);let t;try{await Promise.race([bot.pathfinder.goto(goal),new Promise((_,r)=>t=setTimeout(()=>{bot.pathfinder.setGoal(null);r(Error('GO_BOUND '+p))},6500))]);}finally{clearTimeout(t);bot.pathfinder.setGoal(null);bot.clearControlStates()}await ticks(4);if(!goal.isEnd(bot.entity.position.floored())||!bot.entity.onGround)throw Error('GO_ACTUAL '+p+' '+bot.entity.position);if(!recovery)guard();console.log('STEP',p.toString(),bot.health,mats());}
function cost(p){const q=new Map();for(const d of dirs){const v=p.plus(d);if(!full(bot.blockAt(v)))q.set(v.offset(0,-1,0).toString(),v.offset(0,-1,0));q.set(v.toString(),v);q.set(v.offset(0,1,0).toString(),v.offset(0,1,0));}if(!full(bot.blockAt(p.offset(0,2,0)))){q.set(p.offset(0,2,0).toString(),p.offset(0,2,0));q.set(p.offset(1,2,0).toString(),p.offset(1,2,0));}let n=0;for(const v of q.values())if(!full(bot.blockAt(v))){if(!['air','cave_air'].includes(bot.blockAt(v)?.name))return Infinity;n++}return n;}
async function seal(p){await go(p,true);bot.deactivateItem();for(const d of dirs){const v=p.plus(d);if(!full(bot.blockAt(v))){await put(v.offset(0,-1,0),p.offset(0,-1,0),d);await put(v,v.offset(0,-1,0),new Vec3(0,1,0));}await put(v.offset(0,1,0),v,new Vec3(0,1,0));}if(!full(bot.blockAt(p.offset(0,2,0)))){await put(p.offset(1,2,0),p.offset(1,1,0),new Vec3(0,1,0));await put(p.offset(0,2,0),p.offset(1,2,0),new Vec3(-1,0,0));}await ticks(4);if(!shell(p))throw Error('SHELL_POST');adopted=true;console.log('SHELL_ACTUAL',p.toString(),bot.health,mats());}
async function finish(){bot.pathfinder.setGoal(null);bot.clearControlStates();bot.removeListener('death',die);bot.removeListener('respawn',respawn);bot.removeListener('end',respawn);if(!dead&&!lost){const a=bot.inventory.items().find(i=>i.name==='stone_axe');if(a)await bot.equip(a,'hand');bot.activateItem(true)}console.log('FINAL',JSON.stringify({p:bot.entity.position,hp:bot.health,food:bot.food,dead,lost,adopted,full:shell(bot.entity.position.floored()),mats:mats(),kit:bot.inventory.items().map(i=>[i.name,i.count,i.durabilityUsed]),built,trace:trace.map(p=>[p.x,p.y,p.z])}));}

async function go(p,recovery=false){life();if(!cold(p))throw Error('SHIELD_TARGET '+p);if(p.y!==bot.entity.position.floored().y) return pathGo(p,recovery);bot.pathfinder.setGoal(null);bot.clearControlStates();bot.activateItem(true);const sourceFoot=bot.entity.position.floored(),travelZ=p.z!==sourceFoot.z;try{for(let k=0;k<140;k++){life();if(!recovery)guard();const dx=p.x+.5-bot.entity.position.x,dz=p.z+.5-bot.entity.position.z;if(Math.max(Math.abs(dx),Math.abs(dz))<.12)break;const blaze=Object.values(bot.entities).filter(e=>e.name==='blaze'&&(e.metadata?.[9]??1)>0).sort((a,b)=>a.position.distanceTo(bot.entity.position)-b.position.distanceTo(bot.entity.position))[0];const delta=blaze?blaze.position.minus(bot.entity.position):new Vec3(-10,0,0);const face=Math.abs(delta.x)>=Math.abs(delta.z)?new Vec3(Math.sign(delta.x)||-1,0,0):new Vec3(0,0,Math.sign(delta.z)||-1);await bot.lookAt(bot.entity.position.offset(face.x*10,1.62,face.z*10),true);const lateral=travelZ?Math.abs(dx)>.07:Math.abs(dz)>.07;const chooseX=lateral?travelZ:!travelZ;const desired=chooseX?new Vec3(Math.sign(dx),0,0):new Vec3(0,0,Math.sign(dz));bot.setControlState('sneak',lateral);const dot=desired.x*face.x+desired.z*face.z,right=desired.x*(-face.z)+desired.z*face.x;bot.setControlState(dot>0?'forward':dot<0?'back':right>0?'right':'left',true);await ticks(1);bot.clearControlStates();if(Math.abs(bot.entity.position.y-p.y)>.4)throw Error('SHIELD_DISPLACED');}}finally{bot.clearControlStates()}await ticks(4);if(!bot.entity.onGround||bot.entity.position.distanceTo(p.offset(.5,0,.5))>.35)throw Error('SHIELD_ARRIVAL '+p+' '+bot.entity.position);if(!recovery)guard();console.log('SHIELD_STEP',p.toString(),bot.health,mats());}

