function life(){if(dead||lost||bot.health<=0||bot.game.dimension!=='the_nether')throw Error('LIFE_DISCONTINUITY')};async function ticks(n){life();await bot.waitForTicks(n);life()};function cold(p){return full(bot.blockAt(p.offset(0,-1,0)))&&!bad.includes(bot.blockAt(p.offset(0,-1,0))?.name)&&[0,1].every(y=>bot.blockAt(p.offset(0,y,0))?.boundingBox==='empty'&&!bad.includes(bot.blockAt(p.offset(0,y,0))?.name))};function shell(p){return cold(p)&&full(bot.blockAt(p.offset(0,2,0)))&&dirs.every(d=>[0,1].every(y=>full(bot.blockAt(p.plus(d).offset(0,y,0)))))};
